\begin{align*}
\sin (315^\circ) &= \sin (45^\circ + 270^\circ) \\
&= \sin 45^\circ \cos 270^\circ + \cos 45^\circ \sin 270^\circ \\
&= \frac{\sqrt{2}}{2} \cdot 0 + \frac{\sqrt{2}}{2} \cdot (-1) \\
